def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1
    value = int(state[::-1], 2)

    active = set()
    for offset in offsets:
        offset %= n
        if offset in active:
            active.remove(offset)
        else:
            active.add(offset)

    while t:
        if t & 1:
            result = 0
            for shift in active:
                if shift:
                    result ^= (value >> shift) | ((value << (n - shift)) & mask)
                else:
                    result ^= value
            value = result

        t >>= 1
        if t:
            doubled = set()
            for offset in active:
                offset = (offset * 2) % n
                if offset in doubled:
                    doubled.remove(offset)
                else:
                    doubled.add(offset)
            active = doubled

    return format(value, f"0{n}b")[::-1]
